package com.ptms.service; import com.ptms.domain.*; import com.ptms.dto.*; import com.ptms.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @Transactional public class ReconciliationService{private final ParkingTicketRepository tr;private final ReconciliationRepository rr;public ReconciliationService(ParkingTicketRepository tr,ReconciliationRepository rr){this.tr=tr;this.rr=rr;}public ReconciliationResponse reconcile(ReconciliationRequest q){List<ParkingTicket>a=tr.findByStatusOrderByDurationHoursAscBarcodeAsc(TicketStatus.AVAILABLE);Set<String>expected=new HashSet<>();a.forEach(t->expected.add(t.getBarcode().toLowerCase()));LinkedHashSet<String>scans=new LinkedHashSet<>();if(q.barcodes()!=null)q.barcodes().forEach(b->scans.add(b.trim()));List<String>unknown=scans.stream().filter(b->!expected.contains(b.toLowerCase())).toList();Set<String>known=new HashSet<>();scans.forEach(b->{if(expected.contains(b.toLowerCase()))known.add(b.toLowerCase());});List<String>missing=a.stream().map(ParkingTicket::getBarcode).filter(b->!known.contains(b.toLowerCase())).toList();Reconciliation x=new Reconciliation();x.setReconciliationDate(q.date());x.setPerformedAt(LocalDateTime.now());x.setExpectedAvailable(a.size());x.setScannedCount(scans.size());x.setMissingCount(missing.size());x.setUnknownCount(unknown.size());rr.save(x);return new ReconciliationResponse(a.size(),scans.size(),missing.size(),unknown.size(),missing,unknown);}}
